CREATE TABLE plugin_devicelog_setting_rule_devices (
    ruleId INT NOT NULL,
    deviceId INT NOT NULL,
    CONSTRAINT plugin_devicelog_setting_rule_devices_ruleId_fkey FOREIGN KEY (ruleId) REFERENCES plugin_devicelog_settings_rules(id) ON DELETE CASCADE,
    CONSTRAINT plugin_devicelog_setting_rule_devices_deviceId_fkey FOREIGN KEY (deviceId) REFERENCES devices(id) ON DELETE CASCADE
) ENGINE=InnoDB;
